# 波段猎手 v1 — 跟踪波段高低点，拐点处生成买卖信号
# 逻辑：追踪上一拐点，当价格反向波动 ≥ min_change% 时确认新拐点
# 买：下跌趋势中，价格从低点反弹 ≥ 5%
# 卖：上涨趋势中，价格从高点回落 ≥ 5%

def calc_indicator(ctx):
    df = ctx.kline_df.copy()
    min_change = float(ctx.params.get("min_change", 0.05))
    n = len(df)

    df["buy"] = False
    df["sell"] = False

    if n < 3:
        return df

    last_high = float(df["high"].iloc[0])
    last_low = float(df["low"].iloc[0])
    trend = 0

    for i in range(1, n):
        h = float(df["high"].iloc[i])
        lo = float(df["low"].iloc[i])
        v = float(df["volume"].iloc[i])

        if trend == 0:
            if h > last_low * (1 + min_change):
                trend = 1; last_high = h
            elif lo < last_high * (1 - min_change):
                trend = -1; last_low = lo
            else:
                if h > last_high: last_high = h
                if lo < last_low: last_low = lo

        elif trend == 1:
            if h > last_high: last_high = h
            if lo <= last_high * (1 - min_change):
                df.iloc[i, df.columns.get_loc("sell")] = True
                trend = -1; last_low = lo

        else:
            if lo < last_low: last_low = lo
            if h >= last_low * (1 + min_change):
                vol_avg = df["volume"].iloc[max(0,i-20):i].mean() if i >= 5 else v
                if v > vol_avg * 0.8:
                    df.iloc[i, df.columns.get_loc("buy")] = True
                trend = 1; last_high = h

    return df
